    Definition TFR (M1 : mem) : Prop :=
      cellw SEGS M1 (sp - 8) 8 (bv_unsigned (getr R 1%bv)) /\ cellw SEGS M1 (sp - 16) 8 (bv_unsigned (getr R 8%bv)) /\
      cellw SEGS M1 (sp - 24) 8 (bv_unsigned (getr R 9%bv)) /\ cellw SEGS M1 (sp - 32) 8 (bv_unsigned (getr R 18%bv)) /\
      cellw SEGS M1 (sp - 40) 8 TU_BACK /\ cellw SEGS M1 (sp - 48) 8 pat.

    Definition HI : list reg := [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%bv.
    Definition SAME (R1 : bvmap 5 word) : Prop := forall r, In r HI -> getr R1 r = getr R r.

    Lemma TFR_agree : forall M1 M2, TFR M1 -> agree_on (fun a => zwin (sp - 48) (sp - 32) a \/ zwin (sp - 32) sp a) M1 M2 -> TFR M2.
