    Ltac weq := solve [repeat (first [reflexivity | lia | f_equal])].

    Ltac pinv_grow T H k :=
      lazymatch type of H with ?hd ?A1 ?Mc ?mo ?b1 ?cap1 ?ys =>
        tryif constr_eq Mc T then k H else
        lazymatch T with
        | context [wbytes Mc (Z_to_bv 64 (sp + ?o)) ?bs] =>
            let H' := fresh "PI" in
            assert (H' : hd A1 (wbytes Mc (Z_to_bv 64 (sp + o)) bs) mo b1 cap1 ys) by (eapply (PCargs pinv_stores); [exact H | frame_stores]);
            clear H; pinv_grow T H' k
        | context [wbytes (wbytes Mc (Z_to_bv 64 ?a2) (word_to_le_bytes 4 (Z_to_bv 64 ?x))) (Z_to_bv 64 (pat + 8)) ?bs] =>
            let H' := fresh "PI" in
            assert (H' : hd A1 (wbytes (wbytes Mc (Z_to_bv 64 a2) (word_to_le_bytes 4 (Z_to_bv 64 x))) (Z_to_bv 64 (pat + 8)) bs) mo b1 cap1 (ys ++ [x]))
              by (eapply (PCargs pinv_push_fast); [exact H | zl; lia | lia | zl; weq]);
            clear H; pinv_grow T H' k
        | context [wbytes Mc (Z_to_bv 64 (pat + 8)) ?bs] =>
            let H' := fresh "PI" in
            first
              [ assert (H' : hd A1 (wbytes Mc (Z_to_bv 64 (pat + 8)) bs) mo b1 cap1 ys)
                  by (eapply pinv_set_end; [exact H | zl; weq])
              | assert (H' : hd A1 (wbytes Mc (Z_to_bv 64 (pat + 8)) bs) mo b1 cap1 (removelast ys))
                  by (eapply (PCargs pinv_pop); [exact H | first [exact Hne | apply not_eq_sym; apply app_cons_not_nil | intros X; discriminate X] | pose proof HL1; zl; weq]) ];
            clear H; pinv_grow T H' k
        end
      end.
    Ltac pinv_build T k :=
      lazymatch goal with H0 : TablPush.PINV _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?M0 _ _ _ _ |- _ =>
        lazymatch T with context [M0] => let H := fresh "PI" in pose proof H0 as H; pinv_grow T H k end end.

    Lemma regsU : forall Rk (t0 off : Z) (b1 : Z) (ys : list Z) (cap1 : Z) (wa0 : bool),
      getr Rk 2%bv = Z_to_bv 64 (sp + off) -> getr Rk 8%bv = Z_to_bv 64 pat -> getr Rk 9%bv = Z_to_bv 64 t0 -> getr Rk 18%bv = Z_to_bv 64 5 ->
      (wa0 = true -> getr Rk 10%bv = Z_to_bv 64 (b1 + 4 * Zlen ys)) ->
      regs_ok (Eseed Rk [Z_to_bv 64 sp; Z_to_bv 64 pat; getr R 1%bv; getr R 8%bv; getr R 9%bv; getr R 18%bv; Z_to_bv 64 t0;
                         Z_to_bv 64 (b1 + 4 * Zlen ys); Z_to_bv 64 (b1 + 4 * cap1)])
              (srs sr_id ([(2%bv, EAlu ALU_ADD (EVar 32) (ELit off)); (8%bv, EVar 33); (9%bv, EVar 38); (18%bv, ELit 5)]
                          ++ (if wa0 then [(10%bv, EVar 39)] else []))) Rk.
Proof using R sp pat.
