    Lemma RETK : forall A1 M1 model1 b1 cap1 R2,
      PINV A1 M1 model1 b1 cap1 (snd (take_first xs)) ->
      getr R2 1%bv = getr R 1%bv -> getr R2 2%bv = Z_to_bv 64 sp -> getr R2 8%bv = getr R 8%bv -> getr R2 9%bv = getr R 9%bv ->
      getr R2 18%bv = getr R 18%bv -> SAME R2 ->
      getr R2 10%bv = Z_to_bv 64 (fst (take_first xs)) ->
